export function PricingTable({
  highlightedPlan = "{{highlightedPlan}}",
  period = "{{period}}",
  accent = "{{accent}}",
  radius = {{radius}},
  showBadge = {{showBadge}},
}) {
  const plans = [
    { key: "starter", name: "Starter", price: "$0", features: ["1 project", "Community support"] },
    { key: "pro", name: "Pro", price: "$29", features: ["Unlimited projects", "Priority support", "Team collaboration"] },
    { key: "team", name: "Team", price: "$79", features: ["Everything in Pro", "SSO & audit log", "Dedicated manager"] },
  ];
  return (
    <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 16, fontFamily: "system-ui, sans-serif", color: "#241430" }}>
      {plans.map((plan) => {
        const highlighted = plan.key === highlightedPlan;
        return (
          <div key={plan.key} style={{
            position: "relative", padding: "24px 20px", background: "#FAF7F2",
            border: highlighted ? `1.5px solid ${accent}` : "1.5px solid #24143026",
            borderRadius: radius, boxShadow: highlighted ? "0 8px 24px rgba(36,20,48,.16)" : "none",
            transform: highlighted ? "translateY(-4px)" : "none",
          }}>
            {showBadge && plan.key === "pro" && (
              <span style={{ position: "absolute", top: -12, right: 20, background: accent, color: "#241430",
                fontSize: 11, fontWeight: 600, padding: "4px 10px", borderRadius: 999 }}>
                Most popular
              </span>
            )}
            <h3 style={{ margin: "0 0 8px", fontSize: 16, fontWeight: 600 }}>{plan.name}</h3>
            <p style={{ margin: "0 0 16px", fontSize: 32, fontWeight: 700 }}>
              {plan.price}<span style={{ fontSize: 14, fontWeight: 400, color: "#241430aa" }}>/{period}</span>
            </p>
            <ul style={{ listStyle: "none", margin: "0 0 20px", padding: 0, fontSize: 14, color: "#241430cc", display: "grid", gap: 8 }}>
              {plan.features.map((f) => <li key={f}>{f}</li>)}
            </ul>
            <button type="button" style={{ width: "100%", padding: "10px", borderRadius: 8, border: `1.5px solid ${accent}`,
              background: "transparent", color: "#241430", fontSize: 14, fontWeight: 600, cursor: "pointer" }}>
              Choose {plan.name}
            </button>
          </div>
        );
      })}
    </div>
  );
}
